-- XMASKEDFREAKS ADMIN Media Library
create table if not exists public.media_categories (id text primary key, name text not null, slug text unique not null, description text not null default '', icon text not null default '○', enabled boolean not null default true, archived boolean not null default false, display_order integer not null default 1, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.media_folders (id uuid primary key default gen_random_uuid(), name text not null, slug text not null, parent_id uuid references public.media_folders(id) on delete restrict, path text unique not null, archived boolean not null default false, created_by uuid references public.admin_users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.media_assets (id uuid primary key default gen_random_uuid(), display_name text not null, original_filename text not null, storage_path text unique not null, public_url text not null, thumbnail_url text, mime_type text not null, extension text not null, width integer not null check (width > 0), height integer not null check (height > 0), aspect_ratio numeric(12,6) not null, file_size bigint not null check (file_size > 0), content_hash text not null, category_id text references public.media_categories(id) on delete set null, folder_id uuid references public.media_folders(id) on delete set null, alt_text text not null default '', description text not null default '', tags text[] not null default '{}', status text not null default 'draft' check (status in ('draft','published','private','archived')), focal_point_x numeric(5,4) not null default 0.5 check (focal_point_x between 0 and 1), focal_point_y numeric(5,4) not null default 0.5 check (focal_point_y between 0 and 1), crop_preference text not null default 'original' check (crop_preference in ('original','16:9','4:3','1:1','9:16')), is_animated boolean not null default false, is_public boolean not null default false, game_metadata jsonb not null default '{}'::jsonb, watermark_settings jsonb not null default '{"enabled":false}'::jsonb, uploaded_by uuid references public.admin_users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz);
create table if not exists public.media_variants (id uuid primary key default gen_random_uuid(), media_id uuid not null references public.media_assets(id) on delete cascade, variant_name text not null check (variant_name in ('thumbnail','small','medium','large','original')), storage_path text not null, public_url text not null, width integer not null, height integer not null, file_size bigint, format text not null, created_at timestamptz not null default now(), unique(media_id, variant_name));
create table if not exists public.media_usage (id uuid primary key default gen_random_uuid(), media_id uuid not null references public.media_assets(id) on delete restrict, usage_type text not null, resource_id text, route text, field_name text, created_at timestamptz not null default now(), unique(usage_type, resource_id, field_name));
create table if not exists public.media_action_logs (id uuid primary key default gen_random_uuid(), admin_user_id uuid references public.admin_users(id) on delete set null, action text not null, media_id uuid references public.media_assets(id) on delete set null, previous_values jsonb not null default '{}'::jsonb, new_values jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.site_background_settings (id text primary key default 'default' check (id='default'), enabled boolean not null default false, desktop_media_id uuid references public.media_assets(id) on delete set null, desktop_url text, mobile_media_id uuid references public.media_assets(id) on delete set null, mobile_url text, fallback_media_id uuid references public.media_assets(id) on delete set null, fallback_url text, opacity numeric(5,4) not null default 0.28 check (opacity between 0 and 1), overlay text not null default 'rgba(0,0,0,0.72)', scope text not null default 'global' check (scope in ('global','live','games')), updated_by uuid references public.admin_users(id) on delete set null, updated_at timestamptz not null default now());
alter table public.site_background_settings add column if not exists background_type text not null default 'static';
alter table public.site_background_settings add column if not exists matrix_slim_settings jsonb not null default '{}'::jsonb;
alter table public.site_background_settings add column if not exists video_url text not null default '';
alter table public.site_background_settings add column if not exists focal_point_x numeric(5,4) not null default 0.5;
alter table public.site_background_settings add column if not exists focal_point_y numeric(5,4) not null default 0.5;
alter table public.site_background_settings add column if not exists responsive_scaling boolean not null default true;
alter table public.site_background_settings add column if not exists maximum_pixel_ratio numeric(4,2) not null default 2;
alter table public.site_background_settings add column if not exists resize_debounce_ms integer not null default 75;
alter table public.site_background_settings add column if not exists particle_density_scaling boolean not null default true;
alter table public.site_background_settings add column if not exists maintain_aspect_ratio boolean not null default true;
alter table public.site_background_settings add column if not exists dynamic_resolution boolean not null default true;
alter table public.site_background_settings add column if not exists mobile_performance_mode boolean not null default true;
alter table public.site_background_settings add column if not exists automatic_gpu_optimization boolean not null default true;
create table if not exists public.site_branding_settings (id text primary key default 'default' check (id='default'), logo_media_id uuid references public.media_assets(id) on delete set null, logo_url text not null default '/branding/mask-logo.png', updated_by uuid references public.admin_users(id) on delete set null, updated_at timestamptz not null default now());
alter table public.tip_options add column if not exists media_id uuid;
alter table public.tip_options add column if not exists artwork_url text;
create index if not exists media_assets_created_idx on public.media_assets(created_at desc);
create index if not exists media_assets_category_status_idx on public.media_assets(category_id,status);
create index if not exists media_assets_folder_idx on public.media_assets(folder_id);
create index if not exists media_assets_hash_idx on public.media_assets(content_hash);
create index if not exists media_assets_tags_idx on public.media_assets using gin(tags);
create index if not exists media_usage_media_idx on public.media_usage(media_id);
insert into public.media_categories (id,name,slug,description,icon,display_order) values ('backgrounds','Backgrounds','backgrounds','Global and page background images.','▧',1),('video-backgrounds','Video Backgrounds','video-backgrounds','Approved looping video backgrounds.','▶',2),('interactive-backgrounds','Interactive Backgrounds','interactive-backgrounds','Canvas and interactive background presets.','◎',3),('threejs-presets','Three.js Presets','threejs-presets','Approved WebGL scene presets.','◇',4),('animated-backgrounds','Animated Backgrounds','animated-backgrounds','Animated WebP and GIF backgrounds.','◌',5),('game-thumbnails','Game Thumbnails','game-thumbnails','Game-card and launch artwork.','▣',6),('game-assets','Game Assets','game-assets','Game entities, textures, sprites, and effects.','✦',7),('logos','Logos','logos','Brand marks and identity artwork.','◇',8),('banners','Banners','banners','Live and promotional banners.','▬',9),('live-page','Live Page','live-page','Live-room graphics and overlays.','●',10),('tip-menu','Tip Menu','tip-menu','Tip-card, refill, and modal artwork.','◉',11),('gallery','Gallery','gallery','Reusable gallery images.','▦',12),('merchandise','Merchandise','merchandise','Eligible merchandise imagery.','◆',13),('promotional','Promotional','promotional','Campaign and promotional artwork.','✧',14),('admin-only','Admin Only','admin-only','Private administrator-only visual assets.','◆',15),('other','Other','other','Unclassified image assets.','○',16) on conflict(id) do update set name=excluded.name,description=excluded.description,icon=excluded.icon;
insert into public.media_folders(name,slug,path) select seed.name,seed.slug,seed.slug from (values ('Backgrounds','backgrounds'),('Game Thumbnails','game-thumbnails'),('Game Assets','game-assets'),('Branding','branding'),('Logos','logos'),('Banners','banners'),('Live','live'),('Tip Menu','tip-menu'),('Gallery','gallery'),('Promotions','promotions'),('Mobile','mobile'),('Archived','archived')) as seed(name,slug) where not exists (select 1 from public.media_folders folder where folder.path=seed.slug);
insert into public.site_background_settings(id) values('default') on conflict(id) do nothing;
insert into public.site_branding_settings(id) values('default') on conflict(id) do nothing;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('media','media',false,15728640,array['image/jpeg','image/png','image/webp','image/avif','image/gif']) on conflict(id) do update set public=false,file_size_limit=15728640,allowed_mime_types=excluded.allowed_mime_types;
alter table public.media_categories enable row level security;
alter table public.media_folders enable row level security;
alter table public.media_assets enable row level security;
alter table public.media_variants enable row level security;
alter table public.media_usage enable row level security;
alter table public.media_action_logs enable row level security;
alter table public.site_background_settings enable row level security;
alter table public.site_branding_settings enable row level security;
